create table api.contract(
 id serial primary key,
 number text not null unique check (btrim(number)<>''),
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=new.application_id and s.name='Одобрена') then
  raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation';
 end if;
 return new;
end $$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using (true) with check (true);
create policy lawyer_all on api.contract for all to lawyer using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (
 exists (select 1 from api.application a where a.id=application_id and a.company_inn=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin, lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant usage on schema api to lawyer;
grant select on api.application, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance as
select c.legal_name as company, c.funding_limit, ap.approved,
 coalesce(ct.contracted,0) as contracted, c.funding_limit-coalesce(ct.contracted,0) as remaining
from reg.counterparty c
join (select a.company_inn, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap on ap.company_inn=c.inn
left join (select a.company_inn, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_inn=c.inn;
revoke all on api.limit_balance from public;
grant select on api.limit_balance to fund_admin, lawyer;
grant usage on schema priv to lawyer;
grant execute on all functions in schema priv to lawyer;

